const crypto = require('crypto');
const input = $input.first().json;
const required = ['event_id','event_type','tenant_id'];
for (const key of required) if (!input[key]) throw new Error(`missing ${key}`);
const rawBody = JSON.stringify({
  event_id: input.event_id, event_type: input.event_type, tenant_id: input.tenant_id,
  connection_id: input.connection_id ?? null, conversation_id: input.conversation_id ?? null,
  occurred_at: input.occurred_at ?? new Date().toISOString(), source: 'n8n', version: 1, data: input.data ?? {},
});
const timestamp = String(Math.floor(Date.now()/1000));
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET not configured');
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${input.event_id}.${rawBody}`).digest('hex');
return [{ json: { rawBody, timestamp, signature, event_id: input.event_id, tenant_id: input.tenant_id } }];
